"""Real Linux CPU child/pidfd cleanup using exact v8 source; no Torch/SDK imports."""
import base64,contextlib,hashlib,io,json,linecache,sys,types,unittest
assert not any(n=='torch' or n=='torch_npu' or n.startswith('vllm.') or n=='acl' for n in sys.modules)
source=base64.b64decode('').decode()
module=types.ModuleType('owned_worker_cleanup');module.__file__='/CPU-only-v8/'+'owned_worker_cleanup'+'.py';sys.modules['owned_worker_cleanup']=module
linecache.cache[module.__file__]=(len(source),None,source.splitlines(keepends=True),module.__file__)
exec(compile(source,module.__file__,'exec'),module.__dict__)
source=base64.b64decode('').decode()
module=types.ModuleType('test_owned_cleanup_cpu');module.__file__='/CPU-only-v8/'+'test_owned_cleanup_cpu'+'.py';sys.modules['test_owned_cleanup_cpu']=module
linecache.cache[module.__file__]=(len(source),None,source.splitlines(keepends=True),module.__file__)
exec(compile(source,module.__file__,'exec'),module.__dict__)
body_output=io.StringIO()
with contextlib.redirect_stdout(body_output):
 result=unittest.TextTestRunner(stream=sys.stderr,verbosity=2).run(unittest.defaultTestLoader.loadTestsFromModule(module))
assert not any(n=='torch' or n=='torch_npu' or n.startswith('vllm.') or n=='acl' for n in sys.modules)
proof=json.loads(next(line[len('CPU_DELAYED_SUCCESS '):] for line in body_output.getvalue().splitlines() if line.startswith('CPU_DELAYED_SUCCESS ')))
receipt={'scope':'actual Linux CPU self-created child/pidfd cleanup tests only',
 'tests':result.testsRun,'passed':result.wasSuccessful(),'failures':len(result.failures),'errors':len(result.errors),
 'skipped':len(result.skipped),'delayed_normal_child_proof':proof,
 'normal_success_grace_seconds':45,'failure_uses_success_grace_seconds':0,
 'torch_or_sdk_imported':False,'npu_jobs':0,'device_audit_passed':False,'safe_formal_receipt':False}
assert receipt['passed'] and receipt['tests']==10 and receipt['skipped']==0
assert proof['report']['worker_exit_codes']=={'0':0} and proof['report']['all_terminal']
assert not proof['report']['workers'][0]['hard_kill_sent'] and proof['elapsed_seconds']>5
print(json.dumps(receipt,indent=2))
